1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const CAP_MULTIPLIER = 2;
78	
79	const CURSE_SURCHARGE_RATE = 0.5;
80	const HIGH_ENCHANTMENT_THRESHOLD = 5;
81	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
82	const LOYALTY_YEARS_THRESHOLD = 2;
83	const LOYALTY_DISCOUNT_RATE = 0.2;
84	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
85	
86	const BLOCK_SIZE = 3;
87	const BLOCK_BASE_PREMIUM = 60;
88	
89	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
90	
91	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
92	
93	const countByType = (items: Item[]): Map<string, number> => {
94	  const counts = new Map<string, number>();
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	  return counts;
99	};
100	
101	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
102	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
103	
104	const groupBasePremium = (type: string, count: number): number =>
105	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
106	
107	const policyBasePremium = (items: Item[]): number =>
108	  [...countByType(items)].reduce(
109	    (total, [type, count]) => total + groupBasePremium(type, count),
110	    0,
111	  );
112	
113	// The MHPCO rounds in its own favour: premiums up, payouts down.
114	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
115	
116	// Item-scoped surcharge clauses. Each applies, independently and additively,
117	// to the affected item's own base premium.
118	const ITEM_SURCHARGE_CLAUSES: {
119	  applies: (item: Item) => boolean;
120	  rate: number;
121	}[] = [
122	  {
123	    applies: (item) => item.cursed === true,
124	    rate: CURSE_SURCHARGE_RATE,
125	  },
126	  {
127	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
128	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
129	  },
130	];
131	
132	const itemSurcharge = (item: Item): number => {
133	  const base = itemBasePremium(item);
134	
135	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
136	    (total, clause) => total + base * clause.rate,
137	    0,
138	  );
139	};
140	
141	const itemSurcharges = (items: Item[]): number =>
142	  items.reduce((total, item) => total + itemSurcharge(item), 0);
143	
144	// Everything a policy-scoped clause may inspect.
145	type Policy = {
146	  items: Item[];
147	  customer: Customer;
148	  isFollowUpContract: boolean;
149	};
150	
151	// Policy-scoped modifier clauses. Each applies, independently and additively,
152	// to the policy base premium. A negative rate is a discount.
153	const POLICY_MODIFIER_CLAUSES: {
154	  applies: (policy: Policy) => boolean;
155	  rate: number;
156	}[] = [
157	  {
158	    applies: () => true,
159	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
160	  },
161	  {
162	    applies: (policy) =>
163	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
164	    rate: -LOYALTY_DISCOUNT_RATE,
165	  },
166	  {
167	    applies: (policy) => policy.isFollowUpContract,
168	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
169	  },
170	];
171	
172	const policyModifiers = (policy: Policy, policyBase: number): number =>
173	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
174	    (total, clause) => total + policyBase * clause.rate,
175	    0,
176	  );
177	
178	const quote = (policy: Policy): QuoteResult => {
179	  const policyBase = policyBasePremium(policy.items);
180	  const modifiedPremium =
181	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
182	
183	  return {
184	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
185	  };
186	};
187	
188	const insuranceSum = (items: Item[]): number =>
189	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
190	
191	// A policy issued by a quote step, tracked so later claims can draw on its cap.
192	type IssuedPolicy = {
193	  items: Item[];
194	  remainingCap: number;
195	};
196	
197	const claim = (step: ClaimStep, policy: IssuedPolicy): ClaimResult => {
198	  const payout = step.incident.damages.reduce(
199	    (total, damage) => total + damage.amount - DEDUCTIBLE_PER_DAMAGE,
200	    0,
201	  );
202	  policy.remainingCap -= payout;
203	
204	  return { payout, remainingCap: policy.remainingCap };
205	};
206	
207	export const runScenario = (scenario: Scenario): ScenarioResult => {
208	  let hasIssuedContract = false;
209	  const policies = new Map<number, IssuedPolicy>();
210	
211	  const results = scenario.steps.map((step, index): StepResult => {
212	    if (step.op === "claim") {
213	      return claim(step, policies.get(step.policy)!);
214	    }
215	
216	    policies.set(index, {
217	      items: step.items,
218	      remainingCap: CAP_MULTIPLIER * insuranceSum(step.items),
219	    });
220	
221	    const result = quote({
222	      items: step.items,
223	      customer: scenario.customer,
224	      isFollowUpContract: hasIssuedContract,
225	    });
226	    hasIssuedContract = true;
227	
228	    return result;
229	  });
230	
231	  return { results };
232	};
